commits.patch:
--- a/src/preview.cpp
+++ b/src/preview.cpp
@@ -31,12 +31,12 @@
 /// @brief Decode a Base64 string.
 DataBuf decodeBase64(const std::string& src);

-/// AI7 thumbnails are decoded into a contiguous RGB buffer before being
-/// wrapped as PNM. Keep that temporary allocation bounded.
-constexpr size_t maxAi7ThumbnailSize = 256UL * 1024UL * 1024UL;
-
-/// @brief Calculate and bound-check the decoded RGB size for an AI7 thumbnail.
-bool ai7ThumbnailSize(size_t width, size_t height, size_t& rgbSize);
+/// AI7 thumbnails are decoded into three bytes per pixel before being
+/// wrapped as PNM. Keep the pixel count bounded.
+constexpr size_t maxAi7ThumbnailPixels = 256UL * 1024UL * 1024UL / 3;
+
+/// @brief Calculate and bound-check the pixel count for an AI7 thumbnail.
+bool ai7ThumbnailPixels(size_t width, size_t height, size_t& pixels);

 /// @brief Decode an Illustrator thumbnail that follows after %AI7_Thumbnail.
 DataBuf decodeAi7Thumbnail(const DataBuf& src, size_t expectedSize);
@@ -410,14 +410,14 @@
   }
   if (nativePreview_.filter_ == "hex-ai7thumbnail-pnm") {
     size_t expectedSize = 0;
-    if (!ai7ThumbnailSize(width_, height_, expectedSize)) {
+    if (!ai7ThumbnailPixels(width_, height_, expectedSize)) {
 #ifndef SUPPRESS_WARNINGS
       EXV_WARNING << "Unsupported size of AI7 thumbnail: " << width_ << "x" << height_ << "\n";
 #endif
       return {};
     }
     const DataBuf ai7thumbnail = decodeHex(data + nativePreview_.position_, nativePreview_.size_);
-    const DataBuf rgb = decodeAi7Thumbnail(ai7thumbnail, expectedSize);
+    const DataBuf rgb = decodeAi7Thumbnail(ai7thumbnail, expectedSize * 3);
     return makePnm(width_, height_, rgb);
   }
   if (nativePreview_.filter_ == "hex-irb") {
@@ -825,22 +825,16 @@
   return valid();
 }

-bool ai7ThumbnailSize(size_t width, size_t height, size_t& rgbSize) {
-  rgbSize = 0;
+bool ai7ThumbnailPixels(size_t width, size_t height, size_t& pixels) {
+  pixels = 0;
   if (width == 0 || height == 0)
     return false;

-  constexpr size_t bytesPerPixel = 3;
-
-  if (width > std::numeric_limits<size_t>::max() / height)
+  if (width > maxAi7ThumbnailPixels / height)
     return false;

-  const size_t pixels = width * height;
-  if (pixels > std::numeric_limits<size_t>::max() / bytesPerPixel)
-    return false;
-
-  rgbSize = pixels * bytesPerPixel;
-  return rgbSize <= maxAi7ThumbnailSize;
+  pixels = width * height;
+  return pixels <= maxAi7ThumbnailPixels;
 }

 DataBuf decodeHex(const byte* src, size_t srcSize) {
@@ -968,11 +962,11 @@

 DataBuf makePnm(size_t width, size_t height, const DataBuf& rgb) {
   DataBuf dest;
-  size_t expectedSize = 0;
-  if (!ai7ThumbnailSize(width, height, expectedSize) || rgb.size() != expectedSize) {
+  size_t expectedPixels = 0;
+  if (!ai7ThumbnailPixels(width, height, expectedPixels) || rgb.size() != expectedPixels * 3) {
 #ifndef SUPPRESS_WARNINGS
-    EXV_WARNING << "Invalid size of preview data. Expected " << expectedSize << " bytes, got " << rgb.size()
-                << " bytes.\n";
+    EXV_WARNING << "Invalid size of preview data. Expected " << expectedPixels * 3 << " bytes, got "
+                << rgb.size() << " bytes.\n";
 #endif
     return dest;
   }

--- a/src/preview.cpp
+++ b/src/preview.cpp
@@ -39,7 +39,7 @@
 bool ai7ThumbnailPixels(size_t width, size_t height, size_t& pixels);

 /// @brief Decode an Illustrator thumbnail that follows after %AI7_Thumbnail.
-DataBuf decodeAi7Thumbnail(const DataBuf& src, size_t expectedSize);
+DataBuf decodeAi7Thumbnail(const DataBuf& src, size_t expectedPixels);

 /// @brief Create a PNM image from raw RGB data.
 DataBuf makePnm(size_t width, size_t height, const DataBuf& rgb);
@@ -417,7 +417,7 @@
       return {};
     }
     const DataBuf ai7thumbnail = decodeHex(data + nativePreview_.position_, nativePreview_.size_);
-    const DataBuf rgb = decodeAi7Thumbnail(ai7thumbnail, expectedSize * 3);
+    const DataBuf rgb = decodeAi7Thumbnail(ai7thumbnail, expectedSize);
     return makePnm(width_, height_, rgb);
   }
   if (nativePreview_.filter_ == "hex-irb") {
@@ -912,7 +912,7 @@
   return dest;
 }

-DataBuf decodeAi7Thumbnail(const DataBuf& src, size_t expectedSize) {
+DataBuf decodeAi7Thumbnail(const DataBuf& src, size_t expectedPixels) {
   const byte* colorTable = src.c_data();
   const size_t colorTableSize = 256 * 3;
   if (src.size() < colorTableSize) {
@@ -924,7 +924,7 @@
   const byte* imageData = src.c_data(colorTableSize);
   const size_t imageDataSize = src.size() - colorTableSize;
   const bool rle = (imageDataSize >= 3 && imageData[0] == 'R' && imageData[1] == 'L' && imageData[2] == 'E');
-  DataBuf dest(expectedSize);
+  DataBuf dest(expectedPixels);
   auto destData = dest.data();
   size_t destPos = 0;
   for (size_t i = rle ? 3 : 0; i < imageDataSize;) {
@@ -949,7 +949,7 @@
         value = imageData[i++];
       }
     }
-    Internal::enforce(expectedSize - destPos >= num * 3, ErrorCode::kerCorruptedMetadata);
+    Internal::enforce(expectedPixels * 3 - destPos >= num * 3, ErrorCode::kerCorruptedMetadata);
     const auto c0 = colorTable[value * 3];
     const auto c1 = colorTable[value * 3 + 1];
     const auto c2 = colorTable[value * 3 + 2];
@@ -959,7 +959,7 @@
       destData[destPos++] = c2;
     }
   }
-  Internal::enforce(destPos == expectedSize, ErrorCode::kerCorruptedMetadata);
+  Internal::enforce(destPos == expectedPixels, ErrorCode::kerCorruptedMetadata);
   return dest;
 }
